const URLS = FILES.map((name) => new URL(name, BASE).href);
const ASSETS = new Map(
  FILES.map((name, index) => [URLS[index], INTEGRITY[name]]),
);
const APP = new URL("EduManager.html", BASE).href;
const DOWNLOAD_CONCURRENCY = 4;
const repairs = new Map();
const repairQueue = [];
const REPAIR_TIMEOUT_MS = 8000;
let activeRepairs = 0,
  statusCheck = null,
  activationReady = Promise.resolve();

async function verifyAsset(url, response) {
  const expected = ASSETS.get(url);
  if (!response?.ok || response.redirected || response.type === "opaque")
    throw Error("Incomplete offline download");
  const type = (response.headers.get("Content-Type") || "")
    .split(";")[0]
    .trim()
    .toLowerCase();
  const compatibleType =
    expected &&
    (type === expected[1] ||
      (expected[1] === "application/javascript" &&
        ["text/javascript", "application/ecmascript", "text/ecmascript"].includes(
          type,
        )) ||
      (expected[1] === "application/manifest+json" &&
        type === "application/json"));
  if (!compatibleType) throw Error("Unexpected offline asset content type");
  // Text keeps Git LF/CRLF equivalence; image integrity uses exact raw bytes.
  const bytes =
    expected[1] === "image/png"
      ? await response.clone().arrayBuffer()
      : new TextEncoder().encode(
          (await response.clone().text()).replace(/\r\n/g, "\n"),
        );
  const digest = await crypto.subtle.digest("SHA-256", bytes);
  const actual = Array.from(new Uint8Array(digest), (byte) =>
    byte.toString(16).padStart(2, "0"),
  ).join("");
  if (actual !== expected[0])
    throw Error("Offline asset does not match this release");
}

async function downloadAsset(url, timeout = 0) {
  const controller = timeout ? new AbortController() : null;
  let timer;
  const download = (async () => {
    const response = await fetch(
      new Request(url, {
        cache: "reload",
        credentials: "same-origin",
        ...(controller ? { signal: controller.signal } : {}),
      }),
    );
    await verifyAsset(url, response);
    return response;
  })();
  if (!timeout) return download;
  try {
    return await Promise.race([
      download,
      new Promise((_, reject) => {
        timer = setTimeout(() => {
          controller.abort();
          reject(Error("Offline repair timed out"));
        }, timeout);
      }),
    ]);
  } finally {
    clearTimeout(timer);
  }
}

async function forEachAsset(urls, action) {
  let next = 0,
    failure;
  await Promise.all(
    Array.from(
      { length: Math.min(DOWNLOAD_CONCURRENCY, urls.length) },
      async () => {
        while (!failure && next < urls.length) {
          const url = urls[next++];
          try {
            await action(url);
          } catch (error) {
            failure ||= error || Error("Offline download failed");
          }
        }
      },
    ),
  );
  // In-flight work has settled before a failed staging cache is removed.
  if (failure) throw failure;
}

async function repairAsset(url, cache) {
  if (!repairs.has(url)) {
    const pending = (async () => {
      await new Promise((resolve) => {
        if (activeRepairs < DOWNLOAD_CONCURRENCY) {
          activeRepairs++;
          resolve();
        } else repairQueue.push(resolve);
      });
      try {
        const response = await downloadAsset(url, REPAIR_TIMEOUT_MS);
        try {
          await cache.put(url, response.clone());
        } catch {
          // A storage/quota failure must not prevent verified online use.
          // OFFLINE_STATUS will continue to report the missing cache entry.
        }
        return response;
      } finally {
        const next = repairQueue.shift();
        if (next) next();
        else activeRepairs--;
      }
    })().finally(() => repairs.delete(url));
    repairs.set(url, pending);
  }
  return (await repairs.get(url)).clone();
}

async function offlineStatus() {
  if (!statusCheck)
    statusCheck = (async () => {
      await activationReady;
      const cache = await caches.open(CACHE);
      const responses = await Promise.all(URLS.map((url) => cache.match(url)));
      const missing = URLS.filter((_, index) => !responses[index]);
      if (!missing.length) return true;
      try {
        await forEachAsset(missing, (url) => repairAsset(url, cache));
      } catch {
        // Offline, mismatched and timed-out responses leave the valid shell intact.
      }
      // A verified response may still fail to persist when storage is full.
      return (await Promise.all(URLS.map((url) => cache.match(url)))).every(Boolean);
    })().finally(() => { statusCheck = null; });
  return statusCheck;
}

self.addEventListener("install", (event) =>
  event.waitUntil(
    (async () => {
      // Installation failure never removes the previous active cache.
      await caches.delete(STAGING);
      const cache = await caches.open(STAGING);
      try {
        await forEachAsset(URLS, async (url) => {
          await cache.put(url, await downloadAsset(url));
        });
      } catch (error) {
        await caches.delete(STAGING);
        throw error;
      }
    })(),
  ),
);

self.addEventListener("activate", (event) => {
  activationReady = (async () => {
    const staging = await caches.open(STAGING);
    const responses = await Promise.all(URLS.map((url) => staging.match(url)));
    if (!responses.every(Boolean))
      throw Error("Offline installation is incomplete");
    for (let i = 0; i < URLS.length; i++)
      await verifyAsset(URLS[i], responses[i]);
    const cache = await caches.open(CACHE);
    for (let i = 0; i < URLS.length; i++)
      await cache.put(URLS[i], responses[i]);
    for (const key of await caches.keys()) {
      if (key.startsWith(PREFIX) && key !== CACHE) await caches.delete(key);
    }
    await self.clients.claim();
  })();
  event.waitUntil(activationReady);
});

self.addEventListener("fetch", (event) => {
  if (event.request.method !== "GET") return;
  const url = new URL(event.request.url);
  if (url.origin !== BASE.origin) return;
  const navigation =
    event.request.mode === "navigate" &&
    [
      BASE.pathname,
      new URL("index.html", BASE).pathname,
      new URL("EduManager.html", BASE).pathname,
    ].includes(url.pathname);
  if (navigation || ASSETS.has(url.href)) {
    event.respondWith(
      (async () => {
        await activationReady;
        const cache = await caches.open(CACHE);
        const target = navigation ? APP : url.href;
        return (await cache.match(target)) || repairAsset(target, cache);
      })(),
    );
  }
});

self.addEventListener("message", (event) => {
  if (event.data?.type === "OFFLINE_STATUS")
    event.waitUntil(
      (async () => {
        // A new controller can receive messages before activation finishes promoting files.
        let ready = false;
        try {
          ready = await offlineStatus();
        } catch {}

        event.ports[0]?.postMessage({ ready, version: VERSION });
      })(),
    );
  if (event.data?.type === "APPLY_UPDATE")
    event.waitUntil(
      (async () => {
        const clients = (await self.clients.matchAll({
          type: "window",
          includeUncontrolled: true,
        })).filter((client) => {
          const url = new URL(client.url);
          return url.origin === BASE.origin && url.pathname.startsWith(BASE.pathname);
        });
        if (clients.some((client) => client.id !== event.source?.id)) {
          event.source?.postMessage({ type: "UPDATE_BLOCKED" });
          return;
        }
        await self.skipWaiting();
      })(),
    );
});
